insert into public.level_tips (language, level, interface_language, tip_text, sort_order) values
  ('es', 'A1', 'ru', 'Начни с самых частых слов и фраз: приветствия, числа, дни недели, еда, семья.', 1),
  ('es', 'A1', 'en', 'Start with the most common words and phrases: greetings, numbers, days of the week, food, family.', 1),
  ('es', 'A1', 'es', 'Empieza por las palabras y frases más frecuentes: saludos, números, días de la semana, comida, familia.', 1),
  ('es', 'A1', 'ru', 'Испанский читается почти так, как пишется: выучи правила чтения один раз — и сможешь прочитать любое слово.', 2),
  ('es', 'A1', 'en', 'Spanish is read almost exactly as it is written: learn the reading rules once and you can read any word.', 2),
  ('es', 'A1', 'es', 'El español se lee casi como se escribe: aprende las reglas de lectura una vez y podrás leer cualquier palabra.', 2),
  ('es', 'A1', 'ru', 'Учи существительные сразу с артиклем: el libro, la casa — так род запомнится сам.', 3),
  ('es', 'A1', 'en', 'Learn nouns together with their article: el libro, la casa — the gender will stick by itself.', 3),
  ('es', 'A1', 'es', 'Aprende los sustantivos con su artículo: el libro, la casa; así el género se recuerda solo.', 3),
  ('es', 'A1', 'ru', 'Запоминай ser и estar на простых примерах: soy estudiante, estoy en casa. Разница станет понятнее со временем.', 4),
  ('es', 'A1', 'en', 'Learn ser and estar through simple examples: soy estudiante, estoy en casa. The difference becomes clearer over time.', 4),
  ('es', 'A1', 'es', 'Aprende ser y estar con ejemplos sencillos: soy estudiante, estoy en casa. La diferencia se aclara con el tiempo.', 4),
  ('es', 'A1', 'ru', 'Слушай медленную и чёткую испанскую речь каждый день, хотя бы 5–10 минут.', 5),
  ('es', 'A1', 'en', 'Listen to slow, clear Spanish every day, even if only for 5–10 minutes.', 5),
  ('es', 'A1', 'es', 'Escucha español lento y claro todos los días, aunque sea 5–10 minutos.', 5),
  ('es', 'A1', 'ru', 'Говори вслух с первого дня — даже короткими фразами вроде «Quiero un café, por favor».', 6),
  ('es', 'A1', 'en', 'Speak out loud from day one — even short phrases like «Quiero un café, por favor».', 6),
  ('es', 'A1', 'es', 'Habla en voz alta desde el primer día, aunque sean frases cortas como «Quiero un café, por favor».', 6),
  ('es', 'A1', 'ru', 'Не бойся ошибок: важнее, чтобы тебя поняли, чем идеальная грамматика.', 7),
  ('es', 'A1', 'en', 'Don''t be afraid of mistakes: being understood matters more than perfect grammar.', 7),
  ('es', 'A1', 'es', 'No tengas miedo a equivocarte: es más importante que te entiendan que hablar perfecto.', 7),
  ('es', 'A2', 'ru', 'Освой прошедшее время: pretérito perfecto (he comido) — для того, что было сегодня, indefinido (comí) — для законченного прошлого.', 1),
  ('es', 'A2', 'en', 'Get comfortable with the past: pretérito perfecto (he comido) for what happened today, indefinido (comí) for the finished past.', 1),
  ('es', 'A2', 'es', 'Domina el pasado: el pretérito perfecto (he comido) para lo que ha pasado hoy y el indefinido (comí) para el pasado terminado.', 1),
  ('es', 'A2', 'ru', 'Учи глаголы с чередованием в корне группами: quiero, puedo, duermo (e→ie, o→ue).', 2),
  ('es', 'A2', 'en', 'Learn stem-changing verbs in groups: quiero, puedo, duermo (e→ie, o→ue).', 2),
  ('es', 'A2', 'es', 'Aprende los verbos con cambio de raíz en grupos: quiero, puedo, duermo (e→ie, o→ue).', 2),
  ('es', 'A2', 'ru', 'Рассказывай о своём дне по-испански: что делал утром и что будешь делать вечером.', 3),
  ('es', 'A2', 'en', 'Describe your day in Spanish: what you did this morning and what you''ll do tonight.', 3),
  ('es', 'A2', 'es', 'Cuenta tu día en español: qué hiciste por la mañana y qué vas a hacer por la tarde.', 3),
  ('es', 'A2', 'ru', 'Запоминай готовые фразы для бытовых ситуаций: в кафе, в магазине, у врача.', 4),
  ('es', 'A2', 'en', 'Memorise ready-made phrases for everyday situations: at a café, in a shop, at the doctor''s.', 4),
  ('es', 'A2', 'es', 'Memoriza frases hechas para situaciones cotidianas: en el bar, en la tienda, en el médico.', 4),
  ('es', 'A2', 'ru', 'С gustar глагол согласуется с тем, что нравится: me gusta el café, но me gustan los libros.', 5),
  ('es', 'A2', 'en', 'With gustar the verb agrees with what you like: me gusta el café, but me gustan los libros.', 5),
  ('es', 'A2', 'es', 'Con gustar el verbo concuerda con lo que gusta: me gusta el café, pero me gustan los libros.', 5),
  ('es', 'A2', 'ru', 'Смотри короткие видео на испанском с испанскими субтитрами.', 6),
  ('es', 'A2', 'en', 'Watch short videos in Spanish with Spanish subtitles.', 6),
  ('es', 'A2', 'es', 'Mira vídeos cortos en español con subtítulos en español.', 6),
  ('es', 'A2', 'ru', 'Повторяй выученное через несколько дней — так слова переходят в долговременную память.', 7),
  ('es', 'A2', 'en', 'Review what you''ve learned after a few days — that''s how words move into long-term memory.', 7),
  ('es', 'A2', 'es', 'Repasa lo aprendido a los pocos días: así las palabras pasan a la memoria a largo plazo.', 7),
  ('es', 'B1', 'ru', 'Различай imperfecto и indefinido: imperfecto рисует фон (llovía), indefinido рассказывает события (salí de casa).', 1),
  ('es', 'B1', 'en', 'Tell imperfecto from indefinido: imperfecto sets the scene (llovía), indefinido tells the events (salí de casa).', 1),
  ('es', 'B1', 'es', 'Distingue el imperfecto del indefinido: el imperfecto describe el fondo (llovía) y el indefinido cuenta los hechos (salí de casa).', 1),
  ('es', 'B1', 'ru', 'Начни использовать subjuntivo в частых конструкциях: espero que, quiero que, cuando llegues.', 2),
  ('es', 'B1', 'en', 'Start using the subjunctive in common patterns: espero que, quiero que, cuando llegues.', 2),
  ('es', 'B1', 'es', 'Empieza a usar el subjuntivo en estructuras frecuentes: espero que, quiero que, cuando llegues.', 2),
  ('es', 'B1', 'ru', 'Учи связки, чтобы говорить длиннее: además, sin embargo, por eso, aunque.', 3),
  ('es', 'B1', 'en', 'Learn connectors so you can speak at greater length: además, sin embargo, por eso, aunque.', 3),
  ('es', 'B1', 'es', 'Aprende conectores para hablar de forma más extensa: además, sin embargo, por eso, aunque.', 3),
  ('es', 'B1', 'ru', 'Пересказывай своими словами то, что прочитал или посмотрел.', 4),
  ('es', 'B1', 'en', 'Retell in your own words what you''ve read or watched.', 4),
  ('es', 'B1', 'es', 'Resume con tus propias palabras lo que has leído o visto.', 4),
  ('es', 'B1', 'ru', 'Учи разницу между por и para на примерах, а не по правилам: gracias por todo, es para ti.', 5),
  ('es', 'B1', 'en', 'Learn por vs para from examples rather than rules: gracias por todo, es para ti.', 5),
  ('es', 'B1', 'es', 'Aprende la diferencia entre por y para con ejemplos, no con reglas: gracias por todo, es para ti.', 5),
  ('es', 'B1', 'ru', 'Слушай подкасты для изучающих испанский: естественная скорость, но понятная лексика.', 6),
  ('es', 'B1', 'en', 'Listen to podcasts for Spanish learners: natural speed, but accessible vocabulary.', 6),
  ('es', 'B1', 'es', 'Escucha pódcasts para estudiantes de español: velocidad natural, pero vocabulario accesible.', 6),
  ('es', 'B1', 'ru', 'Записывай свои ошибки и раз в неделю проверяй, повторяются ли они.', 7),
  ('es', 'B1', 'en', 'Keep a list of your mistakes and check once a week whether they repeat.', 7),
  ('es', 'B1', 'es', 'Apunta tus errores y revisa una vez a la semana si se repiten.', 7),
  ('es', 'B2', 'ru', 'Читай и слушай аутентичный контент на любимые темы: новости, сериалы, блоги из Испании.', 1),
  ('es', 'B2', 'en', 'Read and listen to authentic content on topics you love: news, series, blogs from Spain.', 1),
  ('es', 'B2', 'es', 'Lee y escucha contenido auténtico sobre temas que te gusten: noticias, series, blogs de España.', 1),
  ('es', 'B2', 'ru', 'Учи сочетания слов, а не отдельные слова: tomar una decisión, echar de menos.', 2),
  ('es', 'B2', 'en', 'Learn word combinations, not just single words: tomar una decisión, echar de menos.', 2),
  ('es', 'B2', 'es', 'Aprende combinaciones de palabras, no solo palabras sueltas: tomar una decisión, echar de menos.', 2),
  ('es', 'B2', 'ru', 'Тренируй выражение мнения и аргументацию: creo que…, no estoy de acuerdo porque…, en cambio…', 3),
  ('es', 'B2', 'en', 'Practise giving opinions and arguing: creo que…, no estoy de acuerdo porque…, en cambio…', 3),
  ('es', 'B2', 'es', 'Practica dar tu opinión y argumentar: creo que…, no estoy de acuerdo porque…, en cambio…', 3),
  ('es', 'B2', 'ru', 'Освой условные предложения: si tuviera tiempo, viajaría más.', 4),
  ('es', 'B2', 'en', 'Master conditional sentences: si tuviera tiempo, viajaría más.', 4),
  ('es', 'B2', 'es', 'Domina las oraciones condicionales: si tuviera tiempo, viajaría más.', 4),
  ('es', 'B2', 'ru', 'Работай над беглостью: говори дольше, не останавливаясь из-за каждого слова.', 5),
  ('es', 'B2', 'en', 'Work on fluency: speak for longer without stopping at every word.', 5),
  ('es', 'B2', 'es', 'Trabaja la fluidez: habla más tiempo sin detenerte en cada palabra.', 5),
  ('es', 'B2', 'ru', 'Замечай ошибки, которые повторяешь, и исправляй их целенаправленно.', 6),
  ('es', 'B2', 'en', 'Notice the mistakes you keep repeating and fix them on purpose.', 6),
  ('es', 'B2', 'es', 'Fíjate en los errores que repites y corrígelos de forma consciente.', 6),
  ('es', 'B2', 'ru', 'Используй испанский в реальных задачах: переписка, работа, хобби.', 7),
  ('es', 'B2', 'en', 'Use Spanish for real tasks: messages, work, hobbies.', 7),
  ('es', 'B2', 'es', 'Usa el español en tareas reales: mensajes, trabajo, aficiones.', 7),
  ('es', 'C1', 'ru', 'Обращай внимание на регистр: как одну и ту же мысль говорят другу, коллеге и в официальном письме.', 1),
  ('es', 'C1', 'en', 'Pay attention to register: how the same idea is said to a friend, a colleague and in a formal letter.', 1),
  ('es', 'C1', 'es', 'Presta atención al registro: cómo se dice la misma idea a un amigo, a un compañero y en una carta formal.', 1),
  ('es', 'C1', 'ru', 'Учи разговорные выражения Испании: vale, menudo lío, estar hasta las narices.', 2),
  ('es', 'C1', 'en', 'Learn colloquial expressions from Spain: vale, menudo lío, estar hasta las narices.', 2),
  ('es', 'C1', 'es', 'Aprende expresiones coloquiales de España: vale, menudo lío, estar hasta las narices.', 2),
  ('es', 'C1', 'ru', 'Читай качественную прессу и литературу: колонки мнений, современные романы.', 3),
  ('es', 'C1', 'en', 'Read quality press and literature: opinion columns, contemporary novels.', 3),
  ('es', 'C1', 'es', 'Lee prensa y literatura de calidad: columnas de opinión, novela contemporánea.', 3),
  ('es', 'C1', 'ru', 'Тренируй тонкие различия subjuntivo: aunque llueve (факт) и aunque llueva (предположение).', 4),
  ('es', 'C1', 'en', 'Practise subtle subjunctive contrasts: aunque llueve (a fact) and aunque llueva (a possibility).', 4),
  ('es', 'C1', 'es', 'Practica los matices del subjuntivo: aunque llueve (un hecho) y aunque llueva (una posibilidad).', 4),
  ('es', 'C1', 'ru', 'Пиши по-испански — эссе, письма, посты — и проси обратную связь.', 5),
  ('es', 'C1', 'en', 'Write in Spanish — essays, letters, posts — and ask for feedback.', 5),
  ('es', 'C1', 'es', 'Escribe en español —redacciones, cartas, publicaciones— y pide que te corrijan.', 5),
  ('es', 'C1', 'ru', 'Слушай разные акценты Испании: Мадрид, Андалусия, Канарские острова.', 6),
  ('es', 'C1', 'en', 'Listen to different accents of Spain: Madrid, Andalusia, the Canary Islands.', 6),
  ('es', 'C1', 'es', 'Escucha distintos acentos de España: Madrid, Andalucía, Canarias.', 6),
  ('es', 'C1', 'ru', 'Учи синонимы, чтобы не повторяться: decir — comentar, señalar, afirmar.', 7),
  ('es', 'C1', 'en', 'Learn synonyms to avoid repeating yourself: decir — comentar, señalar, afirmar.', 7),
  ('es', 'C1', 'es', 'Aprende sinónimos para no repetirte: decir — comentar, señalar, afirmar.', 7),
  ('es', 'C2', 'ru', 'Погружайся в сложные тексты: эссе, научные и юридические статьи, классическую литературу.', 1),
  ('es', 'C2', 'en', 'Dive into complex texts: essays, scientific and legal articles, classic literature.', 1),
  ('es', 'C2', 'es', 'Sumérgete en textos complejos: ensayos, artículos científicos y jurídicos, literatura clásica.', 1),
  ('es', 'C2', 'ru', 'Изучай пословицы, игру слов и культурные отсылки: refranes, юмор, цитаты.', 2),
  ('es', 'C2', 'en', 'Study proverbs, wordplay and cultural references: refranes, humour, quotations.', 2),
  ('es', 'C2', 'es', 'Estudia refranes, juegos de palabras y referencias culturales: humor, citas, dichos.', 2),
  ('es', 'C2', 'ru', 'Шлифуй точность: выбирай слово, которое передаёт нужный оттенок смысла.', 3),
  ('es', 'C2', 'en', 'Polish your precision: choose the word that carries exactly the nuance you mean.', 3),
  ('es', 'C2', 'es', 'Pule la precisión: elige la palabra que transmite exactamente el matiz que buscas.', 3),
  ('es', 'C2', 'ru', 'Слушай дебаты и интервью и разбирай, как строится аргументация.', 4),
  ('es', 'C2', 'en', 'Listen to debates and interviews and analyse how the arguments are built.', 4),
  ('es', 'C2', 'es', 'Escucha debates y entrevistas y analiza cómo se construyen los argumentos.', 4),
  ('es', 'C2', 'ru', 'Пробуй переводить сложные тексты с родного языка на испанский.', 5),
  ('es', 'C2', 'en', 'Try translating complex texts from your native language into Spanish.', 5),
  ('es', 'C2', 'es', 'Prueba a traducir textos complejos de tu lengua materna al español.', 5),
  ('es', 'C2', 'ru', 'Пиши в разных стилях: от официального письма до неформального поста.', 6),
  ('es', 'C2', 'en', 'Write in different styles: from a formal letter to a casual post.', 6),
  ('es', 'C2', 'es', 'Escribe en distintos estilos: desde una carta formal hasta una publicación informal.', 6),
  ('es', 'C2', 'ru', 'Говори о сложных и абстрактных темах так же свободно, как о повседневных.', 7),
  ('es', 'C2', 'en', 'Talk about complex and abstract topics as freely as about everyday ones.', 7),
  ('es', 'C2', 'es', 'Habla de temas complejos y abstractos con la misma soltura que de los cotidianos.', 7);
